parameters.text:
=Analyze this incoming email:
From: {{ $('Email Content').item.json.from }}
Subject: {{ $('Email Content').item.json.subject }}
Body: {{ $('Email Content').item.json.body }}

parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "subject": {
      "type": "string",
      "description": "The original subject line of the analyzed email."
    },
    "summary": {
      "type": "string",
      "description": "A concise, 1-2 sentence summary of the email content or the job role details."
    },
    "from": {
      "type": "string",
      "description": "The sender's name and email address extracted from the input data."
    },
    "category": {
      "type": "string",
      "enum": ["Indeed", "OLJ", "LinkedIn", "JobStreet", "Upwork", "Other Job", "Not Related Job"],
      "description": "The strict classification of the email based on its source and content."
    },
    "ai_confidence": {
      "type": "integer",
      "minimum": 0,
      "maximum": 100,
      "description": "The model's confidence score for the extraction and classification, represented as a percentage from 0 to 100."
    },
    "ai_reason": {
      "type": "string",
      "description": "A concise, single-sentence summary justifying exactly why the chosen category and confidence score were assigned based on key elements found in the email text."
    }
  },
  "required": ["subject", "summary", "from", "category", "ai_confidence", "ai_reason"]
}

parameters.text:
