parameters.inputSchema:
{
  "$schema": "http://json-schema.org",
  "title": "EmailAnalysisSchema",
  "type": "object",
  "properties": {
    "category": {
      "type": "string",
      "enum": ["JOB_OFFER", "FOLLOW_UP_PROCEDURE", "REJECTION", "UNKNOWN"],
      "description": "The classified status of the incoming recruitment email."
    },
    "confidence_score": {
      "type": "number",
      "minimum": 0.0,
      "maximum": 1.0,
      "description": "Confidence score of the classification from 0.0 to 1.0."
    },
    "sender_company": {
      "type": "string",
      "default": "Unknown",
      "description": "The name of the company sending the email, or 'Unknown' if not found."
    },
    "job_title": {
      "type": "string",
      "default": "Unknown",
      "description": "The job role mentioned in the email, or 'Unknown' if not found."
    },
    "next_action_required": {
      "type": "boolean",
      "description": "True if the candidate needs to reply, schedule, or complete a task. False otherwise."
    },
    "deadline": {
      "type": "string",
      "default": "None",
      "description": "The explicit deadline mentioned in YYYY-MM-DD format, or 'None'."
    },
    "summary": {
      "type": "string",
      "description": "A single-sentence summary of the email context."
    }
  },
  "required": [
    "category",
    "confidence_score",
    "sender_company",
    "job_title",
    "next_action_required",
    "deadline",
    "summary"
  ]
}

